package android.view; public class View { public int width,height,screenX,screenY; public View(){} public View(int w,int h){width=w;height=h;} public boolean getGlobalVisibleRect(android.graphics.Rect r){r.left=r.top=0;r.right=width;r.bottom=height;return true;} public android.content.res.Resources getResources(){return new android.content.res.Resources();} public void getLocationOnScreen(int[] p){p[0]=screenX;p[1]=screenY;} public int getWidth(){return width;} public int getHeight(){return height;} public android.content.Context getContext(){return null;} public WindowInsets insets; public WindowInsets getRootWindowInsets(){return insets;} public Object getParent(){return null;} }